    /// <summary>
    /// Customer Tobacco Licence validations while creating Sales line
    /// </summary>
    /// <param name="sender">Get Table buffer</param>
    /// <param name="e"> Get Sales Table args</param>
    [
        DataEventHandler(tableStr(SalesLine), DataEventType::Inserting),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage") 
    ]
    public static void SalesLine_onInserting(Common sender, DataEventArgs e)
    {
        SalesLine                   salesLine = sender as SalesLine;
        SalesTable                  salesTable = salesLine.salesTable();
        InventDim                   InventDim;
        MetItemSiteSettingsSetup    MetItemSiteSettingsSetup;
        
        select firstonly ItemType from MetItemSiteSettingsSetup 
            where MetItemSiteSettingsSetup.itemId == salesLine.ItemId 
            exists join InventDim 
            where InventDim.inventDimId == salesLine.inventDimId 
            && InventDim.InventSiteId == MetItemSiteSettingsSetup.inventSiteId;

        if(salesTable.METTobaccoLicenceValidationRequired == NoYes::Yes
            && salesTable.METValidTobaccoLicence == NoYes::No
                && METCustParameters::Find().TobaccoFilterCodes == MetItemSiteSettingsSetup.ItemType
                    && salesTable.METCustTobaccoReasonCode)
        {
            salesLine.METCustTobaccoReasonCode = salesTable.METCustTobaccoReasonCode;
            salesLine.Blocked = NoYes::Yes;
        }

        if (!FormDataUtil::isFormDataSource(sender))
        {
            salesLine.METAllowBackOrders = salesLine.metAllowBackorders();
        }
    }

    /// <summary>
    /// Updates the integration status in the METSalesLine table
    /// </summary>
    /// <param name="sender">The salesline buffer</param>
    /// <param name="e"> Get Sales line args</param>
    [
        DataEventHandler(tableStr(SalesLine), DataEventType::Updated),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
    ]
    public static void SalesLine_onUpdated(Common sender, DataEventArgs e)
    {
        SalesLine salesLine = sender as SalesLine;
        METSalesTable    metSalesTable;
        SalesTable       metSalesTableStd;

        if ((salesLine.orig().SalesStatus != SalesStatus::Canceled) && (salesLine.SalesStatus == SalesStatus::Canceled))
        {
            select firstonly RecId from metSalesTableStd
                where metSalesTableStd.SalesId == salesLine.SalesId
                    join RecId from metSalesTable
                where metSalesTable.SalesTable == metSalesTableStd.RecId;

            if(metSalesTable.RecId)
            {
                metSalesTable.updateIntegrationStatus(METIntegrationStatus::ReadyToSend);
            }
        }
    }
